def analyse(R,label):
    R=np.array(R,dtype=float)
    t=R[:,0]; o=R[:,1]; c=R[:,2]
    N=len(c); W=3
    def roll(x,k):
        M=len(x);out=np.full(M,np.nan);v=np.nan_to_num(x)
        cs=np.cumsum(np.insert(v,0,0.0));c2=np.cumsum(np.insert(v*v,0,0.0))
        m=(cs[k:]-cs[:-k])/k; var=(c2[k:]-c2[:-k])/k-m*m
        out[k-1:]=np.sqrt(np.maximum(var,0.0)*k/(k-1)); return out
    r=np.zeros(N); r[1:]=np.log(np.maximum(c[1:],1e-12)/np.maximum(c[:-1],1e-12))
    s20=roll(r,20)
    idx=np.arange(25,N-W-1)
    fwd=np.array([np.max(np.abs(c[i+1:i+1+W]-c[i]))/c[i] for i in idx])
    mon=np.array([dt.datetime.utcfromtimestamp(x/1000).month for x in t[idx]])
    names={1:'Jan',2:'Feb',3:'Mar',4:'Apr',5:'May',6:'Jun',7:'Jul'}
    out={}
    for m in range(1,8):
        k=mon==m
        if k.sum()<8: continue
        x=s20[idx][k]; y=fwd[k]
        ok=np.isfinite(x)&np.isfinite(y)
        if ok.sum()<6: continue
        out[names[m]]=np.corrcoef(x[ok],y[ok])[0,1]
    return out
